head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.questNo;
scwin.gParamObj = new Array(9);
scwin.vScrenID = "ULDSTF30319.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.dateCheck = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_SDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_EDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_EDate.focus();
        return;
    }
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        return false;
    }
};
scwin.fn_list_sync = function() {
    if (scwin.dateCheck() == false) {
        return;
    }
    var SDate = edt_SDate.getValue();
    var EDate = edt_EDate.getValue();
    var url = "/QuestionMgt.do?method=listQuestion&SDate=" + SDate + "&EDate=" + EDate + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_listQuestion.DataID = encodeURI(url);
    dts_listQuestion.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setQuestNo = function(obj) {
    if (scwin.questNo != "input") {
        scwin.questNo = dts_listQuestion.getCellData(eval(obj), "QUEST_NO");
    }
};
scwin.fn_getQuestNo = function() {
    return scwin.questNo;
};
scwin.fn_statUpdate = function(questNo, questStat) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_listQuestion.UserStatus(dts_listQuestion.RowPosition) = 1;*/
    X = 1;
    trs_Update.Action = "/QuestionMgt.do?method=updateStatusQuestion&questNo=" + scwin.questNo + "&questStat=" + questStat;
    trs_Update.KeyValue = "JSP(O:pOutput=dts_listQuestion)";
    trs_Update.Post();
};
scwin.fn_read = function(GridID, row, colid) {
    if (row < 1) return;
    if (colid == "QUEST_RESULT") {
        var url = "/bizspt/ULDSTF30323.gfm?";
        url += "&QUEST_NO=" + scwin.questNo;
        if (scwin.fn_setParam(scwin.questNo)) // formal arguments

        {
            //frame.CreateFrame("ULDSTF30323", "/bizspt/ULDSTF30323.gfm", "결과보기", 200, 10, 820, 720+30, "window",0,0,true);
            $c.frame.path("../../").GWinOpen("child01", url, "결과보기", 200, 10, 820, 720 + 40, "");
        }
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.dts_listQuestion_OnLoadError = function() {
    $c.stf.alert_error(dts_listQuestion);
};
scwin.dts_listQuestion_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_listQuestion.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.btn_Input_onclick = async function() {
    scwin.questNo = "input";
    await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30322.gfm", "설문 등록", 200, 10, 820, 760, "window");
    scwin.questNo = "";
    scwin.fn_list_sync();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == 'QUEST_TITLE' && dts_listQuestion.getCellData(row, "QUEST_STAT_NM") == "진행예정") {
        scwin.fn_setQuestNo(row);
        await $c.frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30322.gfm", "설문 관리", 200, 10, 820, 760, "window");
        scwin.fn_list_sync();
    } else if (colid == "QUEST_RESULT") {
        scwin.fn_setQuestNo(row);
        scwin.fn_read(grd_Grid, row, colid);
        //frame.CreateDialogFrame("gform", "/bizspt/ULDSTF30323.gfm", "결과보기" , 200, 10, 820, 720+30, "window" );

    } else if (colid == "QUEST_STAT_NM") {
        //설문진행전 -> 설문진행중 .... 설문진행중 -> 설문종료,설문중지.... 설문중지 -> 설문진행중
        if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "진행예정" ||
            dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "진행" ||
            dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "중지") {
            var questNo = dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_NO");
            var questStat = "";
            if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "진행예정") {
                if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd")) {
                    questStat = "2";
                }
            } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "진행") {
                if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd") &&
                    dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_DD") >= $c.ut.cGetToday("yyyymmdd")) {
                    questStat = "3";
                } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") <= $c.ut.cGetToday("yyyymmdd") &&
                    dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_NM") <= $c.ut.cGetToday("yyyymmdd")) {
                    questStat = "1";
                }
            } else if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STAT_NM") == "중지") {
                if (dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_STRT_DD") <= $c.ut.cGetToday("yyyymmdd") &&
                    dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_END_DD") >= $c.ut.cGetToday("yyyymmdd")) {
                    questStat = "2";
                }
            }
            if (questStat == "2") {
                var rtn = confirm('설문진행을 하시겠습니까?');
                if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

                {
                    scwin.fn_statUpdate(scwin.questNo, questStat);
                    scwin.fn_list_sync();
                }
            } else if (questStat == "3") {
                var rtn = confirm('설문진행을 중지하시겠습니까?');
                if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

                {
                    scwin.fn_statUpdate(scwin.questNo, questStat);
                    scwin.fn_list_sync();
                }
            } else if (questStat == "1") {
                var rtn = confirm('설문진행을 종료하시겠습니까?');
                if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

                {
                    scwin.fn_statUpdate(scwin.questNo, questStat);
                    scwin.fn_list_sync();
                }
            }
        }
    } else if (colid == "QUEST_PREVIEW") {
        var id = dts_listQuestion.getCellData(dts_listQuestion.getRowPosition(), "QUEST_NO");
        if (id == "") return;
        var url = "/QuestionMgtPreview.do?method=previewQuest&id=" + id;
        await $c.frame.CreateDialogFrame("QUSET_PREVIEW", url, "미리보기", 200, 10, 700, 850, "window");
    }
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 1년전 날짜
    edt_EDate.setValue(vCurDate);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == '1' || js_market == '2') {
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.stf.showObj(panel_mkt, false);
    }
    scwin.fn_list_sync();
};
